    try: os.remove(name)
    except FileNotFoundError: pass
    con = sqlite3.connect(name); con.executescript(ddl); con.commit(); con.close()

base = '''
CREATE TABLE users (
  id integer PRIMARY KEY,
  name varchar(255) NOT NULL,
  age integer NOT NULL DEFAULT 0
);
